command:
if (!game.user.isGM) {
  ui.notifications.warn("GM only.");
  return;
}
const scene = canvas.scene;
if (!scene) {
  ui.notifications.warn("No active scene.");
  return;
}
const labeled = new Set(scene.drawings.filter((d) => d.getFlag("pitax", "pinLabelFor")).map((d) => d.getFlag("pitax", "pinLabelFor")));
const toCreate = [];
let skipped = 0;
for (const note of scene.notes) {
  if (labeled.has(note.id)) continue;
  const label = note.text || note.page?.name || note.entry?.name;
  if (!label) { skipped++; continue; }
  toCreate.push({
    shape: { type: "r", width: 200, height: 30 },
    x: note.x - 100,
    y: note.y + (note.iconSize ?? 40) / 2 + 4,
    fillType: 0,
    strokeWidth: 0,
    text: label,
    fontSize: 24,
    textColor: "#ffffff",
    flags: { pitax: { pinLabelFor: note.id } },
  });
}
if (toCreate.length) await scene.createEmbeddedDocuments("Drawing", toCreate);
ui.notifications.info(`Created ${toCreate.length} pin label(s)${skipped ? `, skipped ${skipped} unlabeled pin(s)` : ""}.`);
